// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.AudioStreamimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.util.HardwareExceptionMapper/** * NOUS — Volume Handler (Module 10 v2 — Step 10.3). * * Handles two operations: *  - [SystemOperation.AdjustVolume] — relative change (delta = +1, -5, etc.) *  - [SystemOperation.SetVolume] — absolute set (level = 50, etc.) * * ## Intelligent Stream Routing (Review 2 Elite 3) * * When the user says "volume up" without specifying a stream, the Brain * classifies it as `AdjustVolume(delta=+1, stream=MEDIA)` (default). The * handler then decides which actual stream to adjust based on device state: * *  - **In a phone call** → adjust `VOICE_CALL` stream (call volume). *  - **Music playing** → adjust `MEDIA` stream (the user's intent). *  - **Otherwise** → use the stream the user specified (default MEDIA). * * If the user explicitly specifies a stream ("ring volume up"), the handler * respects that — it only overrides when the stream is the default `MEDIA`. * * ## Idempotent Execution (Review 2 Elite 1) * * For `SetVolume`: if the current volume is already at the target level, * skip the hardware call (zero-flicker, battery save). * * For `AdjustVolume`: never skip — relative changes always apply (otherwise * "volume up × 3" would only fire once). * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous volume level + stream as `VolumePreState`. Undo * restores the exact previous level — not the inverse (which would be * "delta -1" and could undershoot if the user manually changed volume). * * ## Resource category * * Volume uses [ResourceCategory.AUDIO] — multiple volume operations in a * batch run **sequentially** to avoid AudioManager race conditions. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Architecture — Volume Stream Intelligent Routing</a> */class VolumeHandler(    private val audioService: AudioService,    private val stateProbe: AudioStateProbe,) : ReversibleHandler<SystemOperation> {    override val id: String = "volume"    override val displayName: String = "Volume Control"    override val requiredPermissions: Set<String> = emptySet()    override val resourceCategory: ResourceCategory = ResourceCategory.AUDIO    override fun isAvailable(): Boolean = true  // all devices have AudioManager    // ─── Execute ──────────────────────────────────────────────────────────    override suspend fun execute(operation: SystemOperation): Result<Unit> = when (operation) {        is SystemOperation.AdjustVolume -> executeAdjust(operation)        is SystemOperation.SetVolume -> executeSet(operation)        else -> Result.Failure(            error = AppError.Hardware.Unsupported("volume:${operation::class.simpleName}"),            correlationId = CorrelationId.generate(),            durationNanos = 0,        )    }    private fun executeAdjust(op: SystemOperation.AdjustVolume): Result<Unit> =        HardwareExceptionMapper.withMappingSync("volume") {            val effectiveStream = resolveStream(op.stream)            audioService.adjustStreamVolume(effectiveStream, op.delta)            Result.Success(Unit, CorrelationId.generate(), 0)        }    private fun executeSet(op: SystemOperation.SetVolume): Result<Unit> =        HardwareExceptionMapper.withMappingSync("volume") {            val effectiveStream = resolveStream(op.stream)            audioService.setStreamVolume(effectiveStream, op.level)            Result.Success(Unit, CorrelationId.generate(), 0)        }    // ─── Intelligent stream routing (Review 2 Elite 3) ────────────────────    /**     * Resolve the actual stream to use, applying intelligent routing.     *     * Rule: if the user specified the default `MEDIA` stream AND the device     * is in a call, switch to `VOICE_CALL` (because that's almost certainly     * what the user meant — "volume up" during a call = call volume).     *     * If the user specified any other stream (RING, ALARM, etc.), respect     * their explicit choice.     */    internal fun resolveStream(requested: AudioStream): AudioStream {        if (requested != AudioStream.MEDIA) return requested  // explicit choice — respect it        return when {            stateProbe.isInCall() -> AudioStream.CALL            else -> AudioStream.MEDIA  // default        }    }    // ─── Pre-state capture (Review 2 Fix A) ───────────────────────────────    override suspend fun capturePreState(operation: SystemOperation): Any? {        val stream = when (operation) {            is SystemOperation.AdjustVolume -> resolveStream(operation.stream)            is SystemOperation.SetVolume -> resolveStream(operation.stream)            else -> return null        }        return try {            val currentLevel = audioService.getStreamVolume(stream)            val maxLevel = audioService.getStreamMaxVolume(stream)            VolumePreState(stream = stream, previousLevel = currentLevel, maxLevel = maxLevel)        } catch (t: Throwable) {            Timber.tag("VolumeHandler").w("Failed to capture pre-state", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation, preState: Any?) {        if (preState !is VolumePreState) return        try {            audioService.setStreamVolume(preState.stream, preState.previousLevel)        } catch (t: Throwable) {            Timber.tag("VolumeHandler").w("Failed to restore pre-state", t)        }    }    // ─── Idempotent check (Review 2 Elite 1) ──────────────────────────────    override suspend fun getCurrentState(): Any? = null  // depends on operation    override suspend fun isAlreadyInTargetState(operation: SystemOperation): Boolean {        // Idempotent only for SetVolume — AdjustVolume always applies (relative).        if (operation !is SystemOperation.SetVolume) return false        val stream = resolveStream(operation.stream)        return try {            audioService.getStreamVolume(stream) == operation.level        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation): String = when (operation) {        is SystemOperation.AdjustVolume -> {            val dir = if (operation.delta > 0) "up" else "down"            "Volume ${dir} (${operation.stream.name})"        }        is SystemOperation.SetVolume -> "Volume set to ${operation.level} (${operation.stream.name})"        else -> "Volume operation"    }    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is VolumePreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"VolumePreState\",\"stream\":\"${preState.stream.name}\"," +            "\"previousLevel\":${preState.previousLevel},\"maxLevel\":${preState.maxLevel}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        val type = map["type"] as? String            ?: return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        return when (type) {            "VolumePreState" -> VolumePreState(                stream = AudioStream.valueOf((map["stream"] as? String) ?: "MEDIA"),                previousLevel = (map["previousLevel"] as? Number)?.toInt() ?: 0,                maxLevel = (map["maxLevel"] as? Number)?.toInt() ?: 0,            )            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for volume (stream + previous level + max). */    data class VolumePreState(        val stream: AudioStream,        val previousLevel: Int,        val maxLevel: Int,    )}
